import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useAgentPolicyContextValue } from '../../context'
import {
  getPolicyEditableItemList, submitPolicyEditableItemData, runtimeUpdatePolicyForm,
  validatePostalCode, getAgentPolicyDetails, getReconPolicyDetails, updateCommission,
  validatePolicyData, getInstalmentDetails, generateInstalmentInvoice,
  getCommissionsPointsData,
  submitPolicyEditableItemDataV2
} from '../actions'

export const usePolicyServiceCall = (actionsCall = () => {}) => {
  const [policyState, dispatch] = useAgentPolicyContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [actionsCall, callApi])
  return [policyState, request]
}

export const usePolicyEditItemList = () => usePolicyServiceCall(getPolicyEditableItemList)

export const usePolicyEditItemData = () => usePolicyServiceCall(submitPolicyEditableItemData)

export const usePolicyEditItemDataV2 = () => usePolicyServiceCall(submitPolicyEditableItemDataV2)

export const useUpdatePolicyFormRunTime = () => usePolicyServiceCall(runtimeUpdatePolicyForm)

export const useValidatePostalCode = () => usePolicyServiceCall(validatePostalCode)

export const useGetPolicyDetails = () => usePolicyServiceCall(getAgentPolicyDetails)

export const useGetReconPolicyDetails = () => usePolicyServiceCall(getReconPolicyDetails)

export const useUpdateCommission = () => usePolicyServiceCall(updateCommission)

export const useGetCommissionPoints = () => usePolicyServiceCall(getCommissionsPointsData)

export const useValidatePolicyData = () => usePolicyServiceCall(validatePolicyData)

export const useGetInstalmentDetails = () => usePolicyServiceCall(getInstalmentDetails)

export const useGenerateInstalmentInvoice = () => usePolicyServiceCall(generateInstalmentInvoice)
