import { get } from 'lodash'
import { BIKE_PROTECTION_BASIC, COVID_BASIC, HEALTH_PROTECTION_HCP, JIWA_BASIC, PROFESSIONAL_DATA } from '../constants'
import { getPolicyDataEditField } from '../helpers'

export const getAddressFromObj = (addrObj) => {
  const addrString = `
  ${get(addrObj, 'address')}, 
  ${get(addrObj, 'city_name')} 
  ${get(addrObj, 'postal_code')}, 
  ${get(addrObj, 'province_name')}
  `
  return addrString
}

export const getSpecialNotes = (notes) => {
  const notesArr = []
  for (const key in notes) {
    notesArr.push({
      name: `Notes from ${key}`,
      value: notes[key].remark
    })
  }
  return notesArr
}

export const getSurveyData = (arr) => {
  return arr.map((ele) => {
    const key = Object.keys(ele)[0]
    return {
      name: key,
      value: ele[key]
    }
  })
}

export const getOfflinePolicyData = (policyData = {}) => {
  let productSpecificData = []
  if (get(policyData, 'product_key', '') === 'car-protection') {
    productSpecificData = [
      {
        key: 'offline_product_specific_1',
        name: 'Package',
        value: get(policyData, 'package', '')
      },
      {
        key: 'offline_product_specific_2',
        name: 'Vehicle Type',
        value: get(policyData, 'vehicle_type', '')
      },
      {
        key: 'offline_product_specific_3',
        name: 'Vehicle Year',
        value: get(policyData, 'year', '')
      },
      ...(get(policyData, 'total_cars', '')
        ? [{
            key: 'offline_product_specific_4',
            name: 'Total Cars',
            value: get(policyData, 'total_cars', '')
          }]
        : [])
    ]
  }

  const isCoInsurance = get(policyData, 'is_coinsurance', false)
  const coInsuranceProviders = isCoInsurance
    ? [...get(policyData, 'coinsurance_providers', [])].sort((a, b) => (b.is_leader ? 1 : 0) - (a.is_leader ? 1 : 0))
    : []

  const providerRows = isCoInsurance
    ? coInsuranceProviders.map((p, i) => ({
        key: `offline_co_ins_provider_${i}`,
        name: p.is_leader ? 'Leader Provider Code' : 'Member Provider Code',
        value: p.provider_code,
        value1: (
          <span style={{ display: 'inline-flex', gap: 24 }}>
            {p.share != null && (
              <span>
                <span style={{ color: '#888', marginRight: 5 }}>Share :</span>
                <span style={{ fontWeight: 600 }}>{p.share}%</span>
              </span>
            )}
            {p.provider_branch && (
              <span>
                <span style={{ color: '#888', marginRight: 5 }}>Branch : </span>
                <span>{p.provider_branch}</span>
              </span>
            )}
          </span>
        )
      }))
    : [
        {
          key: 'offline_policy_2',
          name: 'Provider Code',
          value: get(policyData, 'provider_code', '')
        }
      ]

  return [
    {
      key: 'offline_policy_1',
      name: 'Product Key',
      value: get(policyData, 'product_key', '')
    },
    ...providerRows,
    {
      key: 'offline_policy_3',
      name: 'Type of Policy',
      value: get(policyData, 'new_policy', '') ? 'New' : 'Renew'
    },
    {
      key: 'offline_policy_4',
      name: 'Marketing Input Date',
      value: get(policyData, 'marketing_input_date', '')
    },
    {
      key: 'offline_policy_5',
      name: 'Softcopy Issuance Date',
      value: get(policyData, 'softcopy_issue_date', '')
    },
    {
      key: 'offline_policy_6',
      name: 'Application Number',
      value: get(policyData, 'offline_application_no', '')
    },
    {
      key: 'offline_policy_7',
      name: 'Details',
      value: get(policyData, 'details', '')
    },
    ...productSpecificData,
    {
      key: 'offline_policy_8',
      name: 'Hard Copy Required',
      value: get(policyData, 'hard_copy_required', '').toString()
    }
  ]
}

export const getObjectInsuredData = (data = {}) => {
  const pkgDetailRes = get(data, 'request.package_detail_response', {})
  const request = get(data, 'request', {})
  let retdata = {}
  switch (get(pkgDetailRes, 'package.code', '')) {
    case JIWA_BASIC:
      retdata = {
        ...data.additional_detail,
        profession: PROFESSIONAL_DATA[request.profession]
      }
      break
    case BIKE_PROTECTION_BASIC:
      retdata = {
        ...data.additional_detail,
        brand_name: request.brand_name,
        chasis_number: request.chasis_number,
        model_name: request.model_name,
        year: request.year,
        dob: request.dob
      }
      break
    case HEALTH_PROTECTION_HCP:
      retdata = {
        ...data.additional_detail,
        dob: request.dob,
        gender: request.gender === 'M' ? 'Male' : 'Female',
        city_name: request.city_name,
        ktp_no: request.ktp_no
      }
      break
    case COVID_BASIC:
      retdata = {
        dob: request.dob,
        gender: request.gender === 'M' ? 'Male' : 'Female',
        profession: PROFESSIONAL_DATA[request.profession],
        ktp_no: request.ktp_no
      }
      break
    default:
      retdata = {
        ...data.additional_detail,
        variant_code: request.variant_code
      }
  }

  if (get(retdata, 'address', '')) {
    retdata.hardcopy_address = get(retdata, 'address', '')
    delete retdata.address
  }

  return retdata
}

export const getFileNameFromUrl = (url) => {
  if (!url) return null
  const array = url.split('/')
  return array[array.length - 1]
}

export const getEditPolicyBodyReq = (data, defaultData = {}) => {
  const defaultDataArr = [Object.values(defaultData)].flat(Infinity)
  const map = {}
  const newMapWithValidKeys = {}
  for (const key in data) {
    const item = {
      value: data[key]
    }
    if (key === 'vehicle_manufacturing_year') {
      item.value = parseInt(data[key])
    }
    if (['policy_start_date', 'policy_end_date'].includes(key)) {
      item.value = item.value.format('YYYY-MM-DD')
    }
    if (key === 'province_code') {
      item.province_name = data.province_name
    }
    if (key === 'city_code') {
      item.city_name = data.city_name
    }
    if (key === 'premium_note_urls') {
      item.value = item.value.map(url => ({
        url,
        name: getFileNameFromUrl(url)
      }))
    }
    map[key] = {
      ...item
    }
  }
  delete map.city_name
  delete map.province_name
  defaultDataArr.forEach((item) => {
    if (map[item.data_key]) {
      newMapWithValidKeys[item.data_key] = map[item.data_key]
    }
  })
  return newMapWithValidKeys
}

export const getAddonsMapBody = (data) => {
  const obj = {
    add_on: [],
    no_of_pax: 0,
    driver_sum_insured: 0,
    passenger_sum_insured_pax: 0
  }

  for (const key in data) {
    const item = data[key]
    const code = item?.add_on_code || item?.code
    if (code) {
      obj.add_on.push(code)
      const limit = (item.limit === undefined ? item.sum_insured : item.limit)
      if (code === 'passenger-insurance') {
        const count = item.no_passenger || item.add_on_count
        obj.passenger_sum_insured_pax = limit + obj.passenger_sum_insured_pax
        obj.no_of_pax = count + obj.no_of_pax
      } else if (code === 'driver-insurance') {
        obj.driver_sum_insured = limit + obj.driver_sum_insured
      } else {
        const dataKey = `${code.replace(/-/g, '_')}_sum_insured`
        obj[dataKey] = limit || item.premium
      }
    }
  }

  if (!obj.no_of_pax) {
    delete obj.no_of_pax
  }

  if (!obj.passenger_sum_insured_pax) {
    delete obj.passenger_sum_insured_pax
  }

  if (!obj.driver_sum_insured) {
    delete obj.driver_sum_insured
  }

  return obj
}

export const handleValidatePolicyState = (policyState) => {
  switch (policyState) {
    case 'COMPLETED':
    case 'PENDING_ON_AGENT':
    case 'PROVISIONAL_ISSUED':
      return
    default:
      throw Error('policy state should be in COMPLETED, PENDING_ON_AGENT, PROVISIONAL_ISSUED')
  }
}

export const canEditField = (fieldKey, policyState, productId, policyDataEdit) => {
  return getPolicyDataEditField(fieldKey, policyDataEdit) &&
         (policyState === 'COMPLETED' || policyState === 'PROVISIONAL_ISSUED') &&
         (productId === 'car-protection')
}
