import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducers'

export const AgentPolicyContext = createContext()

export const AgentPolicyContextProvider = ({ children }) => {
  return (
    <AgentPolicyContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {children}
    </AgentPolicyContext.Provider>
  )
}

export const useAgentPolicyContextValue = () => useContext(AgentPolicyContext)
