import { get as lodashGet } from 'lodash'
import moment from 'moment'
import { formatMoney } from '../../../../../helpers/utility'

export const handleValidateNIK = (value) => {
  if (!value) return ''
  if (value && value.length !== 16) {
    throw Error('Invalid NIK (NIK must be filled with 16 characters)')
  }
}

export const getPolicyDataEditField = (key, policyDataEdit) => {
  if (!policyDataEdit || !policyDataEdit.is_eligible || !Array.isArray(policyDataEdit.fields)) {
    return false
  }
  const field = policyDataEdit.fields.find(f => f.data_key === key)
  return field?.is_editable ? field : false
}

export const getPremiumBreakup = (policyDetail, agentPolicyDetail) => {
  // Try multiple possible paths for premium_breakup
  let premiumBreakup = lodashGet(policyDetail, 'request.package_detail_response.premium_breakup', null) ||
    lodashGet(policyDetail, 'additional_detail.extra_data', null) ||
    lodashGet(policyDetail, 'payment_detail.premium_breakup', null) ||
    lodashGet(policyDetail, 'premium_breakup', null) ||
    lodashGet(agentPolicyDetail, 'premium_breakup', null) ||
    lodashGet(agentPolicyDetail, 'payment_detail.premium_breakup', null) ||
    lodashGet(agentPolicyDetail, 'request.package_detail_response.premium_breakup', null)

  // If it's a string, try to parse it
  if (typeof premiumBreakup === 'string' && premiumBreakup.trim()) {
    try {
      premiumBreakup = JSON.parse(premiumBreakup)
    } catch (e) {
      premiumBreakup = null
    }
  }

  // Default to empty object if still null or invalid
  if (!premiumBreakup || typeof premiumBreakup !== 'object') {
    premiumBreakup = {}
  }

  return premiumBreakup
}

export const checkShowYearWiseBreakup = (policyDetail, premiumBreakup) => {
  // Extract year keys (numeric keys like "1", "2", "3")
  const allKeys = Object.keys(premiumBreakup)
  const yearKeys = allKeys
    .filter(key => /^\d+$/.test(String(key)))
    .sort((a, b) => parseInt(a) - parseInt(b))

  // Check if it's a multi-year policy
  const packageCode = lodashGet(policyDetail, 'request.package_code', '') ||
                      lodashGet(policyDetail, 'request.package_type', '') ||
                      lodashGet(policyDetail, 'request.package_detail_response.package.code', '')
  const isMultiYearPolicy = packageCode && packageCode.includes('multiyear')

  // If premium_breakup exists and has year data, show year-wise breakdown ONLY for multi-year policies
  const showYearWiseBreakup = isMultiYearPolicy && yearKeys.length > 0 && premiumBreakup && typeof premiumBreakup === 'object'

  return {
    showYearWiseBreakup,
    yearKeys
  }
}

export const formatPercent = (value) => {
  if (!value && value !== 0) return '-'
  return `${value}%`
}

export const formatDate = (dateString) => {
  if (!dateString || dateString === '-') return '-'
  try {
    const date = moment(dateString)
    if (date.isValid()) {
      return date.format('DD/MM/YYYY')
    }
    return dateString
  } catch (e) {
    return dateString
  }
}

export const formatMoneyForSummary = (value) => {
  if (!value && value !== 0) return '-'
  const numValue = typeof value === 'string' ? parseFloat(value.replace(/,/g, '')) : value
  return formatMoney(numValue || 0)
}

export const getYearCoverageDates = (year, overallStartDate, overallEndDate) => {
  if (!overallStartDate || overallStartDate === '-') {
    return { start: '-', end: '-' }
  }

  try {
    const startMoment = moment(overallStartDate)
    const endMoment = moment(overallEndDate)

    if (!startMoment.isValid()) {
      return { start: '-', end: '-' }
    }

    const yearNum = parseInt(year)
    const yearStart = startMoment.clone().add(yearNum - 1, 'years')
    let yearEnd = yearNum === 1
      ? startMoment.clone().add(1, 'year').subtract(1, 'day')
      : startMoment.clone().add(yearNum, 'years').subtract(1, 'day')

    if (endMoment.isValid() && yearEnd.isAfter(endMoment)) {
      yearEnd = endMoment.clone()
    }

    return {
      start: yearStart.format('DD/MM/YYYY'),
      end: yearEnd.format('DD/MM/YYYY')
    }
  } catch (e) {
    return { start: '-', end: '-' }
  }
}
