import { POLICY_ACTIONS } from './actions'
export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload } = action

  switch (type) {
    case POLICY_ACTIONS.GET_POLICY_EDITABLE_ITEMS_LIST:
    case POLICY_ACTIONS.POLICY_EDITABLE_ITEMS_DATA:
    case POLICY_ACTIONS.RUNTIME_UPDATE_FORM:
    case POLICY_ACTIONS.VALIDATE_POSTAL_CODE:
    case POLICY_ACTIONS.GET_POLICY_DETAILS:
    case POLICY_ACTIONS.GET_RECON_POLICY_DETAILS:
    case POLICY_ACTIONS.UPDATE_COMMISSION_REQUEST:
    case POLICY_ACTIONS.VALIDATE_POLICY:
    case POLICY_ACTIONS.GENERATE_INSTALMENT_INVOICE:
    case POLICY_ACTIONS.GET_INSTALMENT_DETAILS:
    case POLICY_ACTIONS.GET_COMMISSIONS_POINTS:
      return {
        ...state,
        ...payload
      }
    default:
      return state
  }
}

export default reducer
